begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('d7000000-0000-4000-8000-000000000001','dental-staff@example.test','{"first_name":"Dental","last_name":"Staff"}'),('d7000000-0000-4000-8000-000000000002','dental-inactive@example.test','{"first_name":"Inactive","last_name":"Staff"}');
update public.profiles set is_active = true where id in ('d7000000-0000-4000-8000-000000000001','d7000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('d7000000-0000-4000-8000-000000000001','STAFF'),('d7000000-0000-4000-8000-000000000002','STAFF');

update public.profiles set is_active=false where id='d7000000-0000-4000-8000-000000000002';
create temp table dental_fixture(kind text primary key,id uuid);grant all on dental_fixture to authenticated;
select is(cardinality(public.dental_tooth_numbers('dog','adult')),42,'Dog adult tooth count verified');
select is(cardinality(public.dental_tooth_numbers('cat','adult')),30,'Cat adult tooth count verified');
select is(cardinality(public.dental_tooth_numbers('dog','deciduous')),28,'Dog deciduous tooth count verified');
select is(cardinality(public.dental_tooth_numbers('cat','deciduous')),26,'Cat deciduous tooth count verified');
select ok(not('105'=any(public.dental_tooth_numbers('cat','adult'))),'Feline adult P1 gap preserved');
select ok(not('806'=any(public.dental_tooth_numbers('cat','deciduous'))),'Feline deciduous mandibular P2 gap preserved');
select ok(not has_table_privilege('authenticated','public.dental_charts','UPDATE'),'Direct chart editing denied');
select ok(not has_table_privilege('service_role','public.dental_charts','UPDATE'),'Service role cannot bypass chart RPCs');
select ok(not has_table_privilege('authenticated','public.dental_chart_revisions','DELETE'),'Revision deletion denied');
select ok(not has_table_privilege('anon','public.dental_charts','SELECT'),'Anonymous clinical data access denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d7000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into dental_fixture select 'client',id from public.save_client(auth.uid(),null,null,'Synthetic','Dental',null,null,'EMAIL',null,null);
insert into dental_fixture select 'dog',id from public.save_patient(null,(select id from dental_fixture where kind='client'),null,'Dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into dental_fixture select 'cat',id from public.save_patient(null,(select id from dental_fixture where kind='client'),null,'Cat','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into dental_fixture select 'rabbit',id from public.save_patient(null,(select id from dental_fixture where kind='client'),null,'Rabbit','Rabbit',null,null,'unknown',null,'unknown','unknown',null,null,null);
select throws_ok($$select public.save_dental_chart(gen_random_uuid(),(select id from dental_fixture where kind='dog'),null,'',now(),'','{}')$$,'23514','Select an appropriate dentition','Dentition must be explicit');
select throws_ok($$select public.save_dental_chart(gen_random_uuid(),(select id from dental_fixture where kind='rabbit'),null,'adult',now(),'','{}')$$,'23514','Select an appropriate dentition','Unsupported species cannot get fabricated standard chart');
select lives_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),null,'adult',now(),'','{}')$$,'Create empty dog chart without assumed findings');
select is((select teeth from public.dental_charts where id='d7100000-0000-4000-8000-000000000001'),'{}'::jsonb,'No teeth premarked normal');
select lives_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),null,'adult',now(),'','{}')$$,'Lost create response retry idempotent');
select is((select count(*) from public.dental_chart_revisions),1::bigint,'Retry creates no duplicate revision');
select throws_ok($$select public.sign_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),1)$$,'23514','Record observations or notes before signing','Blank dental chart cannot be signed');
select throws_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='cat'),1,'adult',now(),'Mismatch','{}')$$,'42501','Chart does not belong to patient','Cross-patient draft write rejected');
select throws_ok($$select public.save_dental_chart(gen_random_uuid(),(select id from dental_fixture where kind='cat'),null,'adult',now(),'','{"105":{"presence":"present","findings":"","planned":"","performed":"","measurements":[]}}')$$,'23514','Invalid tooth for selected dentition','Wrong feline tooth ID rejected');
select throws_ok($$select public.save_dental_chart(gen_random_uuid(),(select id from dental_fixture where kind='dog'),null,'deciduous',now(),'','{"101":{"presence":"present","findings":"","planned":"","performed":"","measurements":[]}}')$$,'23514','Invalid tooth for selected dentition','Permanent ID cannot be stored in deciduous chart');
select throws_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),1,'adult',now(),'','{"101":{"presence":"present","findings":"","planned":"","performed":"","measurements":[{"label":"Buccal","value_mm":-1}]}}')$$,'23514','Measurements require a label and positive finite millimeters','Negative measurement rejected');
select throws_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),1,'adult',now(),'','{"101":{"presence":"present","findings":"","planned":"","performed":"","measurements":[{"label":"Buccal","value_mm":"NaN"}]}}')$$,'23514','Measurements require a label and positive finite millimeters','Nonfinite string measurement rejected');
select lives_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),1,'adult',now(),'Exam recorded','{"101":{"presence":"missing","findings":"Not observed","planned":"Review imaging","performed":"","measurements":[]}}')$$,'Save observed missing tooth');
select lives_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),1,'adult',now(),'Exam recorded','{"101":{"presence":"missing","findings":"Not observed","planned":"Review imaging","performed":"","measurements":[]}}')$$,'Lost update response retry idempotent');
select is((select version from public.dental_charts where id='d7100000-0000-4000-8000-000000000001'),2,'Version advances once');
select throws_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),1,'adult',now(),'Stale overwrite','{}')$$,'40001','Dental chart changed; reload before saving','Stale draft cannot replace saved observations');
select throws_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),2,'deciduous',now(),'Change template','{}')$$,'23514','Saved chart dentition cannot change','Saved template identity is preserved');
select lives_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),2,'adult',now(),'Corrected after review','{"101":{"presence":"extracted","findings":"Historical extraction confirmed","planned":"","performed":"","measurements":[]}}')$$,'Correction retains tooth marker');
select is((select teeth->'101'->>'presence' from public.dental_chart_revisions where chart_id='d7100000-0000-4000-8000-000000000001' and version=2),'missing','Earlier missing-tooth observation remains in history');
select throws_ok($$select public.sign_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='cat'),3)$$,'42501','Chart does not belong to patient','Cross-patient signing denied');
select lives_ok($$select public.sign_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),3)$$,'Sign reviewed chart');
select is((select signed_by from public.dental_charts where id='d7100000-0000-4000-8000-000000000001'),auth.uid(),'Signer stamped from session');
select lives_ok($$select public.sign_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),3)$$,'Lost sign response replay idempotent');
select throws_ok($$select public.save_dental_chart('d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),4,'adult',now(),'Overwrite signed','{}')$$,'23514','Signed chart is immutable; add a correction instead','Signed original cannot change');
select throws_ok($$select public.add_dental_addendum(gen_random_uuid(),'d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='cat'),'Wrong patient')$$,'42501','Chart does not belong to patient','Cross-patient addendum denied');
select lives_ok($$select public.add_dental_addendum('d7200000-0000-4000-8000-000000000001','d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),'Corrected description; original retained')$$,'Add correction to signed history');
select lives_ok($$select public.add_dental_addendum('d7200000-0000-4000-8000-000000000001','d7100000-0000-4000-8000-000000000001',(select id from dental_fixture where kind='dog'),'Corrected description; original retained')$$,'Retry addendum idempotent');
select is((select count(*) from public.dental_chart_addenda),1::bigint,'Only one correction stored');
select is((select count(*) from public.dental_chart_revisions),4::bigint,'Draft revisions and signed snapshot retained');
select lives_ok($$select public.save_dental_chart(gen_random_uuid(),(select id from dental_fixture where kind='rabbit'),null,'manual',now(),'Species-specific narrative review','{}')$$,'Unsupported species manual notes supported');
select set_config('request.jwt.claims','{"sub":"d7000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.dental_charts),0::bigint,'Inactive staff cannot read charts');
select throws_ok($$select public.save_dental_chart(gen_random_uuid(),(select id from dental_fixture where kind='dog'),null,'adult',now(),'Inactive','{}')$$,'42501','Active staff access required','Inactive staff cannot write');
select * from finish();rollback;
